"""A tiny cooperative scheduler, so tests control exactly how tasks interleave.

Real services use asyncio; this stands in for it so every run is the same.
A task runs until it awaits yield_control(), then the next task gets a turn.
"""
import types


class Deadlock(Exception):
    """Tasks are still waiting after far more turns than any of them needs."""


@types.coroutine
def yield_control():
    """Let the other tasks run (think: waiting on the network)."""
    yield


class Lock:
    def __init__(self):
        self._held = False

    async def acquire(self):
        while self._held:
            await yield_control()
        self._held = True

    def release(self):
        self._held = False

    async def __aenter__(self):
        await self.acquire()

    async def __aexit__(self, *exc_info):
        self.release()


def run_all(*coroutines, max_turns=100):
    """Runs coroutines round-robin until they all finish; returns each one's result or its exception."""
    pending = list(enumerate(coroutines))
    results = [None] * len(coroutines)
    turns = 0
    while pending:
        turns += 1
        if turns > max_turns:
            raise Deadlock("still waiting after %d turns" % max_turns)
        still_running = []
        for index, task in pending:
            try:
                task.send(None)
            except StopIteration as done:
                results[index] = done.value
            except Exception as error:
                results[index] = error
            else:
                still_running.append((index, task))
        pending = still_running
    return results

