from sched import yield_control


class InsufficientFunds(Exception):
    pass


class AccountService:
    def __init__(self, store):
        self.store = store

    async def withdraw(self, account_id, cents):
        balance, version = self.store.read(account_id)
        await yield_control()  # e.g. a fraud check between reading the balance and writing it back
        if balance < cents:
            raise InsufficientFunds(account_id)
        self.store.write(account_id, balance - cents, version)
        return balance - cents

